/**
 * Segwit address layer: `encode(hrp, witver, witprog)` and `decode(hrp, addr)`.
 *
 * `encode` validates by round-tripping through `decode`, exactly as the Python
 * package does, and returns `null` (Python's `None`) whenever that round trip
 * rejects the address it just built.  Note that this build checksums every
 * witness version with plain Bech32 -- there is no Bech32m variant.
 */

import { bech32Decode, bech32Encode } from './codec.mjs';
import { convertBits } from './convertbits.mjs';

const MAX_WITNESS_VERSION = 16n;
const MIN_PROGRAM_LENGTH = 2;
const MAX_PROGRAM_LENGTH = 40;
const VERSION_ZERO_LENGTHS = [20, 32];

/** `decode(hrp, addr)` -> `[witver, witprog]` or `[null, null]`. */
export function decode(hrp, addr) {
  const [decodedHrp, data] = bech32Decode(addr);
  if (decodedHrp !== hrp) return [null, null];

  const program = convertBits(data.slice(1), 5, 8, false);
  if (
    program === null ||
    program.length < MIN_PROGRAM_LENGTH ||
    program.length > MAX_PROGRAM_LENGTH
  ) {
    return [null, null];
  }
  if (data[0] > MAX_WITNESS_VERSION) return [null, null];
  if (data[0] === 0n && !VERSION_ZERO_LENGTHS.includes(program.length)) {
    return [null, null];
  }
  return [data[0], program];
}

/** `encode(hrp, witver, witprog)` -> the address string, or `null`. */
export function encode(hrp, witver, witprog) {
  const fiveBitProgram = convertBits(witprog, 8, 5);
  if (fiveBitProgram === null) return null;

  const address = bech32Encode(hrp, [witver, ...fiveBitProgram]);
  const [decodedVersion, decodedProgram] = decode(hrp, address);
  if (decodedVersion === null && decodedProgram === null) return null;
  return address;
}

/**
 * CPython's `int(str)` conversion, base 10.
 *
 * Values are returned as BigInt because Python integers are unbounded: the
 * witness version reaches `CHARSET[witver]` unchanged, and the difference
 * between "string index out of range" and "cannot fit 'int' into an index-sized
 * integer" depends on the true magnitude, not on a clamped double.
 *
 * Accepted grammar (after stripping Python whitespace from both ends):
 *
 *     [+-] digit (('_')? digit)*
 *
 * where `digit` is any Unicode decimal digit, and underscores may neither lead,
 * trail, nor repeat.
 */

import { decimalDigitValue, isPythonSpace } from './unicode.mjs';
import { PythonValueError } from './errors.mjs';
import { pythonRepr } from './repr.mjs';

const PLUS = 0x2b;
const MINUS = 0x2d;
const UNDERSCORE = 0x5f;

/** Parses like `int()` but reports failure as `null` instead of raising. */
export function parsePythonInt(text) {
  const codePoints = Array.from(text, (character) => character.codePointAt(0));

  let start = 0;
  let end = codePoints.length;
  while (start < end && isPythonSpace(codePoints[start])) start += 1;
  while (end > start && isPythonSpace(codePoints[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (codePoints[start] === PLUS || codePoints[start] === MINUS)) {
    negative = codePoints[start] === MINUS;
    start += 1;
  }

  let digits = '';
  // Doubles as "an underscore here would be illegal": true before the first
  // digit and immediately after an underscore.
  let awaitingDigit = true;
  for (let index = start; index < end; index += 1) {
    const codePoint = codePoints[index];
    if (codePoint === UNDERSCORE) {
      if (awaitingDigit) return null;
      awaitingDigit = true;
      continue;
    }
    const value = decimalDigitValue(codePoint);
    if (value < 0) return null;
    digits += String(value);
    awaitingDigit = false;
  }
  // Catches an empty body as well as a trailing underscore.
  if (awaitingDigit) return null;

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/** `int(text)`; raises `ValueError` with CPython's message on bad input. */
export function pythonInt(text) {
  const value = parsePythonInt(text);
  if (value === null) {
    throw new PythonValueError(
      `invalid literal for int() with base 10: ${pythonRepr(text)}`,
    );
  }
  return value;
}
