/**
 * Traceback rendering for the frozen `test4` script.
 *
 * The reference build is a PyInstaller bundle, so an unhandled exception prints
 * a CPython traceback whose frames point at the original `test4.py` source
 * lines, followed by PyInstaller's own one-line summary.  Frames inside the
 * bundled `bech32` package have no source text available, so only their
 * location lines appear.
 */

import { writeStderr } from './stdio.mjs';

const SCRIPT_MODULE = 'test4';
const SCRIPT_FILE = 'test4.py';
const LIBRARY_FILE = 'bech32/__init__.py';

const MODULE_FRAME = {
  file: SCRIPT_FILE,
  line: 16,
  name: '<module>',
  source: 'main()',
};

/** Frames for a failure inside `witprog = list(map(int, args.c.split(',')))`. */
export const CONVERT_ARGUMENT_FRAMES = [
  MODULE_FRAME,
  {
    file: SCRIPT_FILE,
    line: 11,
    name: 'main',
    source: "witprog = list(map(int, args.c.split(',')))",
    anchorStart: 'witprog = '.length,
  },
];

/** Frames for a failure raised out of `bech32.encode(...)`. */
export const ENCODE_FRAMES = [
  MODULE_FRAME,
  {
    file: SCRIPT_FILE,
    line: 12,
    name: 'main',
    source:
      'result = bech32.encode(args.a, args.b, witprog)  # Encode segwit address',
    anchorStart: 'result = '.length,
    // The anchor covers the call only, not the trailing comment.
    anchorEnd: 'result = bech32.encode(args.a, args.b, witprog)'.length,
  },
  { file: LIBRARY_FILE, line: 127, name: 'encode' },
  { file: LIBRARY_FILE, line: 61, name: 'bech32_encode' },
];

function frameLines(frame) {
  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.name}`];
  if (frame.source === undefined) return lines;
  lines.push(`    ${frame.source}`);
  if (frame.anchorStart !== undefined) {
    const end = frame.anchorEnd ?? frame.source.length;
    lines.push(
      `    ${' '.repeat(frame.anchorStart)}${'^'.repeat(end - frame.anchorStart)}`,
    );
  }
  return lines;
}

/**
 * Prints the traceback for an unhandled exception exactly as the frozen build
 * does, including PyInstaller's trailing failure notice.
 */
export function reportUnhandledException(error, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) lines.push(...frameLines(frame));
  lines.push(`${error.typeName}: ${error.pythonMessage}`);
  lines.push(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_MODULE}' due to unhandled exception!`,
  );
  writeStderr(`${lines.join('\n')}\n`);
}

